head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정   
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:150px; height:50px;" 
    let cStyleParent = scwin.gVar["cStyleParent"];


    let properties = {
        style: cStyle,
    };

    let cList = $c.gcm.createCList(properties);   

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp    
    );

    strTarget += '<xf:trigger ' + strNameSpace + ' ' + cList + '><xf:label><![CDATA[trigger]]></xf:label></xf:trigger>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "trigger",
        strTarget,
        parent1
    );
}
